package net.officefloor.hq.app.period;

import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.InvalidClaimStatusException;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Refuses opening a claim whose period (the one containing its due-by) caps the open claims per
 * person, when its person already has that many OPEN or PENDING claims due by a date in it.
 */
public class CheckPeriodCap {
    public void check(@Val Sheet sheet, @Val Claim claim, PeriodRepository periods, ClaimRepository claims)
            throws InvalidClaimStatusException {
        Period full = full(sheet, claim, periods, claims);
        if (full != null) {
            throw new InvalidClaimStatusException("Period " + full.name() + " allows at most " + full.cap()
                    + " open claims per person");
        }
    }

    /** The capped period the claim belongs to when its person is already at the cap, else null. */
    public static Period full(Sheet sheet, Claim claim, PeriodRepository periods, ClaimRepository claims) {
        if (claim.getDueBy() == null) return null;
        Period period = periods.on(sheet.id(), claim.getDueBy());
        if (period == null || period.cap() == null) return null;
        long held = claims.findByPerson(sheet.id(), claim.getPersonId()).stream()
                .filter(c -> c.getId() != claim.getId())
                .filter(c -> c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
                .filter(c -> c.getDueBy() != null && period.contains(c.getDueBy()))
                .count();
        return held >= period.cap() ? period : null;
    }
}
